CREATE TABLE IF NOT EXISTS chain_liquidations (id TEXT PRIMARY KEY, wallet TEXT NOT NULL, reason TEXT NOT NULL, pre_collateral TEXT NOT NULL, post_collateral TEXT, maintenance_margin TEXT NOT NULL, positions_closed_json TEXT NOT NULL, tx_hash TEXT, ledger INTEGER NOT NULL, status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_chain_liquidations_wallet_ledger ON chain_liquidations(wallet, ledger DESC);
CREATE TABLE IF NOT EXISTS chain_orders (id TEXT PRIMARY KEY, wallet TEXT NOT NULL, series TEXT NOT NULL, side TEXT NOT NULL, price_ticks TEXT NOT NULL, quantity TEXT NOT NULL, remaining TEXT NOT NULL, time_in_force TEXT NOT NULL, sequence INTEGER NOT NULL, status TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS chain_trades (id TEXT PRIMARY KEY, buy_order_id TEXT NOT NULL, sell_order_id TEXT NOT NULL, quantity TEXT NOT NULL, price_ticks TEXT NOT NULL, settlement_status TEXT NOT NULL, tx_hash TEXT, created_at INTEGER NOT NULL);
